// The Describe interface provides a human-readable type description
pub interface Describe {
  fn describe() -> Str;
}

// A custom derive for Describe would:
// 1. Read the struct definition from the AST
// 2. For each field, generate a description like "field_name: field_type"
// 3. Combine all field descriptions into a single string
// 4. Generate the impl Describe block

impl Describe for Int {
  fn describe() -> Str { return "a whole number"; }
}

fn main() -> Int {
  return 42;
}
